-- Catalog candidate seed generated from the supplied tracking, Changeover, and Page Audit sheets.
-- Review docs/CATALOG_IMPORT_REVIEW.md before running; this does not import tasks, URLs, notes, or passwords.
begin;

insert into public.model_years (year) values
  (2014),
  (2016),
  (2017),
  (2018),
  (2019),
  (2020),
  (2021),
  (2022),
  (2023),
  (2024),
  (2025),
  (2026),
  (2027),
  (2028),
  (2029)
on conflict (year) do nothing;

-- The workbook identifies 2027 as the current Changeover year. Make it the default only if none is set.
do $$ begin
  if not exists (select 1 from public.model_years where is_default) then
    update public.model_years set state = 'prior' where year < 2027 and state = 'draft';
    update public.model_years set state = 'active', is_default = true where year = 2027;
  end if;
end $$;

